from pathlib import Path
p=Path('/mnt/data/DPPCC_NEW')
def page(title,body,extra=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Official DPPCC cricket club website"><title>{title} | DPPCC</title><link rel="stylesheet" href="css/style.css"></head><body><div data-nav></div>{body}<div data-footer></div><script src="https://www.gstatic.com/firebasejs/8.10.1/firebase-app.js"></script><script src="https://www.gstatic.com/firebasejs/8.10.1/firebase-auth.js"></script><script src="https://www.gstatic.com/firebasejs/8.10.1/firebase-firestore.js"></script><script src="js/app.js"></script>{extra}</body></html>'''
pages={
'index.html':page('Home','''<main><section class="hero"><div class="hero-inner"><div><div class="kicker">DPPCC · OFFICIAL CRICKET CLUB</div><h1>DUNGSREE PASCHIM PARA <span>CRICKET CLUB</span></h1><p>One club. One team. One passion. Play with pride, grow together and represent our community through tennis ball cricket.</p><div class="actions"><a class="btn" href="register.html">JOIN THE TEAM</a><a class="btn secondary" style="color:white;border-color:white" href="matches.html">MATCH CENTRE</a></div></div></div></section><div class="ticker">DPPCC · PLAY · FRIENDSHIP · UNITY · ESTABLISHED 2026</div><section class="wrap"><div class="heading"><small>CLUB UPDATES</small><h2>WELCOME TO DPPCC</h2><p>Latest highlights from our cricket community</p></div><div class="grid" id="newsList"><div class="card">Loading latest highlights...</div></div></section><section class="wrap"><div class="statrow"><div class="stat"><b>2026</b>Established</div><div class="stat"><b>Tennis Ball</b>Cricket</div><div class="stat"><b>DPPCC</b>One Team</div></div></section></main>'''),
'about.html':page('About','''<main class="wrap"><div class="heading"><small>WHO WE ARE</small><h1>ABOUT OUR CLUB</h1><p>A community united by cricket.</p></div><div class="card"><h3>Club History</h3><p>Dungsree Paschim Para Cricket Club is a cricket community built on teamwork, discipline, friendship and a love for the game. Established in 2026, DPPCC aims to create opportunities for players and bring our community together through cricket.</p><h3>Our Mission</h3><p>To encourage participation, develop cricketing skills and build a respectful, united team.</p><h3>Our Vision</h3><p>To become a respected community cricket club known for sportsmanship, teamwork and positive impact.</p><h3>Established 2026</h3><p>Our club began in 2026. Sponsor branding references 2003 separately and does not represent the club's founding year.</p></div></main>'''),
'players.html':page('Players','''<main class="dark"><section class="wrap"><div class="heading"><small>THE SQUAD</small><h1>PLAYER DIRECTORY</h1><p>Every player matters. Every run counts.</p></div><div class="grid" id="playersList"><div class="card">Loading players...</div></div></section></main>'''),
'register.html':page('Player Registration','''<main class="wrap"><div class="heading"><small>BE PART OF DPPCC</small><h1>PLAYER REGISTRATION</h1><p>Register your interest in joining the club.</p></div><div class="formbox"><h3>Player Registration Form</h3><form id="registrationForm"><label>Full Name</label><input name="name" maxlength="70" required><label>Phone Number</label><input name="phone" maxlength="20" required><label>Age</label><input name="age" type="number" min="8" max="70" required><label>Playing Role</label><select name="role" required><option value="">Select role</option><option>Batsman</option><option>Bowler</option><option>All-Rounder</option><option>Wicket Keeper</option></select><label>Address</label><textarea name="address" maxlength="120" required></textarea><button>SUBMIT REGISTRATION</button><div id="registrationFormMessage" class="status hidden"></div></form></div></main>'''),
'jersey.html':page('Jersey Order','''<main class="wrap"><div class="heading"><small>OFFICIAL CLUB KIT</small><h1>DPPCC JERSEY ORDER</h1><p>Place your club jersey order online.</p></div><div class="formbox"><h3>Jersey Order Form</h3><form id="jerseyForm"><label>Your Name</label><input name="name" maxlength="70" required><label>Phone Number</label><input name="phone" maxlength="20" required><label>Jersey Size</label><select name="size" required><option value="">Choose size</option><option>S</option><option>M</option><option>L</option><option>XL</option><option>XXL</option></select><label>Jersey Number (0–99)</label><input name="number" type="number" min="0" max="99" required><button>SUBMIT JERSEY ORDER</button><div id="jerseyFormMessage" class="status hidden"></div></form></div></main>'''),
'matches.html':page('Matches','''<main class="dark"><section class="wrap"><div class="heading"><small>FIXTURES & RESULTS</small><h1>MATCH CENTRE</h1><p>Fixtures, results and live score updates.</p></div><div class="grid" id="matchesList"><div class="card">Loading matches...</div></div><div class="heading" style="margin-top:38px"><h2>LIVE SCORE</h2></div><div id="liveScoresList" class="card">No live score updates yet.</div></section></main>'''),
'news.html':page('News','''<main class="wrap"><div class="heading"><small>CLUB UPDATES</small><h1>NEWS & ANNOUNCEMENTS</h1></div><div class="grid" id="newsList"><div class="card">Loading news...</div></div></main>'''),
'sponsor.html':page('Sponsor','''<main class="wrap"><div class="heading"><small>OUR SUPPORT</small><h1>OFFICIAL SPONSOR</h1></div><div class="sponsor"><img src="assets/dppcc-sponsor-2003.jpg" alt="DPPCC Sponsor"><div><h2>SPONSORED BY MD SHIPON AHMED</h2><p>2003 · Sponsor branding</p><p>Thank you for supporting our cricket family.</p></div></div></main>'''),
'login.html':page('Staff Login','''<main class="wrap"><div class="heading"><small>AUTHORIZED ACCESS</small><h1>DPPCC STAFF LOGIN</h1><p>Secure access for authorized club officials only.</p></div><div class="formbox"><form id="loginForm"><label>Email Address</label><input name="email" type="email" required autocomplete="username"><label>Password</label><input name="password" type="password" required autocomplete="current-password"><button>SECURE LOGIN</button><p><a href="#" id="forgotPassword">Forgot password?</a></p><div id="loginMessage" class="status hidden"></div></form></div></main>''')}
for role in ['owner','admin','captain','manager']:
 title=role.title();
 body=f'''<main class="dashboard" data-role="{title}"><div class="card"><h1 id="dashWelcome">{title} Dashboard</h1><p id="dashEmail"></p><button id="logoutButton" class="danger">LOG OUT</button><div class="tabs"><a href="index.html">Public Website</a></div></div>'''
 if role in ['owner','admin','captain']:
  body+='''<section class="card" data-permission="players"><h2>Players</h2><form id="dashPlayerForm"><label>Player Name</label><input name="name" required><label>Role</label><select name="role"><option>Batsman</option><option>Bowler</option><option>All-Rounder</option><option>Wicket Keeper</option></select><label>Jersey Number</label><input name="jerseyNo" type="number" min="0" max="999" required><label>Photo URL (optional HTTPS)</label><input name="photoUrl" type="url"><button>ADD PLAYER</button></form><div id="dashPlayers"></div></section>'''
 if role in ['owner','admin','captain','manager']:
  body+='''<section class="card" data-permission="matches"><h2>Matches</h2><form id="dashMatchForm"><label>Opponent</label><input name="opponent" required><label>Date</label><input name="date" type="date" required><label>Venue</label><input name="venue"><label>Status</label><select name="status"><option>Upcoming</option><option>Live</option><option>Completed</option></select><label>Result</label><input name="result"><button>SAVE MATCH</button></form><div id="dashMatches"></div></section>'''
 if role in ['owner','admin','captain']:
  body+='''<section class="card" data-permission="live"><h2>Live Score Update</h2><form id="dashBallForm"><label>Match label</label><input name="matchLabel" required><label>Over</label><input name="over" type="number" min="0" required><label>Ball</label><input name="ball" type="number" min="1" max="6" required><label>Runs</label><input name="runs" type="number" min="0" max="6" required><label>Wicket?</label><select name="wicket"><option value="false">No</option><option value="true">Yes</option></select><label>Commentary</label><input name="commentary"><button>PUBLISH BALL</button></form></section>'''
 if role in ['owner','admin']:
  body+='''<section class="card" data-permission="news"><h2>Publish News</h2><form id="dashNewsForm"><label>Title</label><input name="title" required><label>Announcement</label><textarea name="body" required></textarea><button>PUBLISH NEWS</button></form></section>'''
 if role in ['owner','admin','manager']:
  body+='''<section class="card" data-permission="submissions"><h2>Player Registrations</h2><div id="dashRegs"></div><h2>Jersey Orders</h2><div id="dashOrders"></div></section>'''
 if role=='owner':
  body+='''<section class="card" data-permission="staff"><h2>Staff Account & Role Management</h2><p>Create or change access for existing Firebase Authentication accounts. This does not create Gmail accounts or passwords.</p><form id="staffForm"><label>Staff Gmail Address</label><input name="email" type="email" required><label>Position</label><select name="role"><option>Admin</option><option>Captain</option><option>Manager</option></select><label><input name="active" type="checkbox" checked style="width:auto"> Allow this account to log in</label><button>SAVE STAFF ACCESS</button><div id="staffMessage" class="status hidden"></div></form><div id="staffList"></div></section><section class="card" data-permission="backup"><h2>Database Backup</h2><button id="backupButton">DOWNLOAD JSON BACKUP</button></section>'''
 body+='</main>'
 pages[f'{role}.html']=page(f'{title} Dashboard',body)
for name,content in pages.items():(p/name).write_text(content,encoding='utf-8')
(p/'README_BN.txt').write_text('''DPPCC WEBSITE UPDATE – INSTALLATION\n\nএই ZIP-এ আলাদা আলাদা পেজ দেওয়া হয়েছে। একই GitHub repository-তে পুরোনো index.html এবং সংশ্লিষ্ট পুরোনো HTML ফাইলগুলো replace করে ZIP-এর সব ফাইল upload করুন। css এবং js folder-সহ upload করতে হবে। assets folder-এ আগের logo ও sponsor image রাখবেন।\n\nগুরুত্বপূর্ণ: assets/dppcc-club-logo.jpg এবং assets/dppcc-sponsor-2003.jpg আগের repository থেকে assets folder-এ রেখে দিন। ZIP-এ image file নেই।\n\nFirebase project: dppcc-official (আগেরটাই)। Firestore collection names: players, matches, registrations, jerseyOrders, staff, liveScores, news. আগের Firestore Rules অপরিবর্তিত রাখুন।\n\nStaff login: login.html. Role অনুযায়ী owner.html, admin.html, captain.html, manager.html-এ যাবে। Owner email code-এ mdshiponahmed0455@gmail.com। Staff account Firebase Authentication-এ আগে তৈরি থাকতে হবে; Owner Dashboard থেকে role assign করতে হবে।\n\nনোট: Firebase Rules আগের মতো role-based access বজায় রাখে। এই package-এ public data read, public registration/order submission, এবং dashboard actions আগের collection schema অনুসারে করা হয়েছে। GitHub-এ publish করার আগে test করুন।\n''',encoding='utf-8')
